import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unsent invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);
  assert.equal(issueResult.ok, true);

  const text = renderInvoiceText(issueResult.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2025-0001');
});

test('renderInvoiceText includes customer name', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows items with qty, name, unit price, and total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Line with the item
  assert.match(lines[2], /^5 Development \(hour\)/);
  assert.match(lines[2], /€95\.00/); // unit price
  assert.match(lines[2], /€475\.00/); // line total
});

test('renderInvoiceText formats prices with formatEuros', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // LOGO-PACK is 120000 cents = €1,200.00
  assert.match(lines[2], /€1,200\.00/);
});

test('renderInvoiceText shows total line', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount, 21% VAT
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // 47500, with 5% discount = 45125, VAT 21% = 9476.25
      { sku: 'LOGO-PACK', qty: 1 }, // 120000, with 5% discount = 114000, VAT 21% = 23940
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  const totalLine = lines.find((l) => l.includes('Total:'));
  // Gold tier has discount, so shows expanded format
  assert.match(totalLine, /Subtotal:/);
  assert.match(totalLine, /Discount:/);
  assert.match(totalLine, /Total:/);
  // Subtotal = 167500, Discount = 8375, VAT = 33416, Total = 192541
  assert.match(totalLine, /€1,925\.41/);
});

test('renderInvoiceText with single item', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'SUPPORT-HOUR', qty: 3 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should have: DRAFT, customer, item, VAT line, total line = 5 lines
  assert.equal(lines.length, 5);
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert.match(lines[2], /^3 Support \(hour\)/);
  assert.match(lines[3], /^VAT: /);
  // Gold tier has discount, so shows expanded format
  assert.match(lines[4], /Subtotal:/);
  assert.match(lines[4], /Discount:/);
  assert.match(lines[4], /Total:/);
});

test('renderInvoiceText with multiple items', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier: 2.5% discount
    issueDate: '2025-02-20',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 4 },
      { sku: 'ICON-SET', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  // DRAFT, customer, 3 items, VAT line, total = 7 lines
  assert.equal(lines.length, 7);
  assert.match(lines[2], /^2 Development \(hour\)/);
  assert.match(lines[3], /^4 Copywriting \(hour\)/);
  assert.match(lines[4], /^3 Icon set/);
  assert.match(lines[5], /^VAT: /);
  // Silver tier has discount, so shows expanded format
  assert.match(lines[6], /Subtotal:/);
  assert.match(lines[6], /Discount:/);
  assert.match(lines[6], /Total:/);
});

test('renderInvoiceText preserves line breaks structure', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should have: DRAFT, customer, 2 items, VAT line, total
  assert.equal(lines.length, 6);
  assert(lines[0]); // invoice number
  assert(lines[1]); // customer
  assert(lines[2]); // first item
  assert(lines[3]); // second item
  assert(lines[4]); // VAT line
  assert(lines[5]); // total
});

test('renderInvoiceText with issued invoice and full data', () => {
  const createResult = createInvoice({
    customerId: 'C-008', // Lumen Records: gold tier: 5% discount
    issueDate: '2025-03-10',
    lines: [
      { sku: 'PRINT-A4', qty: 500 }, // 9% VAT
      { sku: 'PRINT-A3', qty: 100 }, // 9% VAT
    ],
  });

  assert.equal(createResult.ok, true);
  const issueResult = issueInvoice(createResult.value, ['INV-2025-0001']);
  assert.equal(issueResult.ok, true);

  const text = renderInvoiceText(issueResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2025-0002'); // next number
  assert.equal(lines[1], 'Lumen Records');
  assert.match(lines[2], /^500 Printed flyer A4/);
  assert.match(lines[3], /^100 Printed poster A3/);
  // Should have VAT line
  assert.match(lines[4], /^VAT: /);
  // Gold tier has discount, so shows expanded format
  assert.match(lines[5], /Subtotal:/);
  assert.match(lines[5], /Discount:/);
  assert.match(lines[5], /Total:/);
});

test('renderInvoiceText formats small amounts correctly', () => {
  const result = createInvoice({
    customerId: 'C-006', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'STICKER', qty: 1 }], // 21% VAT
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // STICKER is 50 cents = €0.50
  assert.match(lines[2], /€0\.50/);
  // VAT line: 21% of 0.50 = 0.105, rounds to 0.10 (banker's rounding: 10.5 rounds to 10)
  assert.match(lines[3], /€0\.10/);
});

test('renderInvoiceText with high-value items', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount, 21% VAT
    issueDate: '2025-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // BRAND-BOOK is 245000 cents = €2,450.00
  assert.match(lines[2], /€2,450\.00/);
  // Check VAT line exists
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  assert(vatLine);
  // 2 * 245000 = 490000, with 5% discount = 465500, VAT 21% = 97755
  assert.match(vatLine, /€977\.55/);
});

test('renderInvoiceText shows discount on line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should show discount info on the item line
  assert.match(lines[2], /10% off/);
  assert.match(lines[2], /-€47\.50/);
});

test('renderInvoiceText shows subtotal and discount in total line when discounts present', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no tier discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 }, // 21% VAT
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }, // 21% VAT
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  const totalLine = lines.find((l) => l.includes('Total:'));

  // Should show subtotal, discount, and total
  assert.match(totalLine, /Subtotal:/);
  assert.match(totalLine, /Discount:/);
  assert.match(totalLine, /Total:/);
  // Subtotal should be 95 + 1200 = 1295
  assert.match(totalLine, /€1,295\.00/);
  // Discount should be 19 + 120 = 139
  assert.match(totalLine, /-€139\.00/);
  // Amount after discount = 1295 - 139 = 1156
  // VAT = 21% of 1156 = 242.76
  // Total = 1156 + 242.76 = 1398.76
  assert.match(totalLine, /€1,398\.76/);
});

test('renderInvoiceText with multiple items with different discounts', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-03-10',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 15 },
      { sku: 'SUPPORT-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 3, discountPercent: 25 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Check that discounts are shown for items with discounts
  assert.match(lines[2], /15% off/);
  assert(!lines[3].includes('% off')); // SUPPORT-HOUR has no discount
  assert.match(lines[4], /25% off/);
});

test('renderInvoiceText without tier discounts shows simple total line', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: 0% discount (no tier discount)
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  const totalLine = lines[lines.length - 1];

  // Standard tier has no discount, so shows simple "Total: " format
  assert.match(totalLine, /^Total: /);
  assert(!totalLine.includes('Subtotal'));
  assert(!totalLine.includes('Discount'));
});

test('renderInvoiceText shows VAT line', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should have: DRAFT, customer, item, VAT line, total line
  assert.equal(lines.length, 5);
  // VAT line should be second to last
  assert.match(lines[lines.length - 2], /^VAT: €/);
  // 95.00 with 21% VAT = 19.95
  assert.match(lines[lines.length - 2], /€19\.95/);
});

test('renderInvoiceText with multiple items and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 95.00, 21% VAT = 19.95
      { sku: 'PRINT-A4', qty: 100 }, // 3.70 with bulk discount 2.5% = 3.61, 9% VAT = 3.25
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should show VAT line
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  assert(vatLine);
  // VAT should be 19.95 + 3.25 = 23.20 (with bulk discount on qty 100)
  assert.match(vatLine, /€23\.20/);
});

test('renderInvoiceText without VAT does not show VAT line', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // 0% VAT
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should NOT have a VAT line
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  assert(!vatLine);
  // Should just have DRAFT, customer, item, total
  assert.equal(lines.length, 4);
});

test('renderInvoiceText with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should show discount info
  assert.match(lines[2], /5% off/);
  // Should show VAT line
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  assert(vatLine);
  // 95 - (95 * 0.05) = 90.25, VAT 21% of 90.25 = 18.9525, rounds to 1895
  assert.match(vatLine, /€18\.95/);
  // Should show expanded total line
  const totalLine = lines[lines.length - 1];
  assert.match(totalLine, /Subtotal:/);
  assert.match(totalLine, /Discount:/);
  assert.match(totalLine, /Total:/);
});

