import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './invoices.js';
import { formatEuros } from './money.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Customer name
  const customerResult = getCustomer(invoice.customerId);
  if (customerResult.ok) {
    lines.push(customerResult.value.name);
  }

  // Item lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(total)}`;

    // Add discount if present
    if (line.discountPercent) {
      const discount = lineDiscount(line);
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }

    lines.push(lineText);
  }

  // VAT and total lines
  const totals = invoiceTotals(invoice);

  // Show VAT if present
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Show voucher if present
  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  // Total line
  let totalLine = `Total: ${formatEuros(totals.total)}`;
  if (totals.discount > 0) {
    totalLine = `Subtotal: ${formatEuros(totals.subtotal)} Discount: -${formatEuros(totals.discount)} Total: ${formatEuros(totals.total)}`;
  }
  lines.push(totalLine);

  // Due date line if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid line if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

